void * frrscript_get_result ( struct frrscript * fs , const char * function_name , const char * name , void * * lua_to ( lua_State * L , int idx ) ) { void * p ; struct lua_function_state * lfs ; struct lua_function_state lookup = { . name = function_name } ; lfs = hash_lookup ( fs -> lua_function_hash , & lookup ) ; assert ( lua_gettop ( lfs -> L ) == 1 ) ; assert ( lua_istable ( lfs -> L , - 1 ) == 1 ) ; lua_getfield ( lfs -> L , - 1 , name ) ; if ( lua_isnil ( lfs -> L , - 1 ) ) { lua_pop ( lfs -> L , 1 ) ; zlog_warn ( "frrscript: '%s.lua': '%s': tried to decode '%s' as result but failed" , fs -> name , function_name , name ) ; return NULL ; } p = lua_to ( lfs -> L , 2 ) ; assert ( lua_gettop ( lfs -> L ) == 1 ) ; assert ( lua_istable ( lfs -> L , - 1 ) == 1 ) ; return p ; } 